import re,json,hashlib
from pathlib import Path
out=Path('target/native-target-final-checks');a=re.findall(r'^(.+): test$',(out/'native-test-list.log').read_text(),re.M);b=re.findall(r'test (\S+) \.\.\. ok',(out/'native-tests.log').read_text());assert len(a)==len(set(a))==224 and set(a)==set(b)
(out/'test-inventory.json').write_text(json.dumps(dict(listed=a,observed=b,registered_count=len(a),registered_all_observed=True,limits='Nested child-test stdout may repeat/interleave prefixes; complete name and ok suffix matched anywhere. Registered set equality, not process count.'),indent=2)+'\n')
old=Path('docs/evidence/nested-milestone/2026-10-18-native-foundation/runtime/execution.json');prior=json.loads(old.read_text());current=json.loads((out/'executables.json').read_text());names=['fluxwm','fluxwm-config','fluxwm-fixture'];matches={name:current[str(Path('target/debug',name).resolve())]==prior['executables'][str(Path('target/debug',name).resolve())] for name in names};assert all(matches.values());assert len(prior['runs'])==5 and all(x['exit_code']==0 for x in prior['runs']);assert all(hashlib.sha256(Path(k).read_bytes()).hexdigest()==v for k,v in current.items())
(out/'nested-binary-continuity.json').write_text(json.dumps(dict(prior_evidence=str(old),prior_record_sha256=hashlib.sha256(old.read_bytes()).hexdigest(),unchanged_nested_binaries=matches,prior_successful_gui_runs=5,new_gui_runs=0,scope='Same compositor/config/fixture bytes as prior GUI qualification. New probe audited separately; no new GUI or native hardware execution.'),indent=2)+'\n')
audit=json.load(open('target/native-target-final-readonly-audit/result.json'));assert audit['ok'] and audit['binary_sha256']==current[str(Path('target/debug/fluxwm-native-probe').resolve())]
assert len(json.load(open(out/'checks.json')))==11 and all(row['exit_code']==0 for row in json.load(open(out/'checks.json')))
print('224 registered tests observed; checks and read-only audit passed; nested binary continuity verified')
